<style>
.wa10-public{background:#fff;border:1px solid #dce7ed;border-top:3px solid #16a393;border-radius:12px;padding:20px 22px;margin:16px 0 22px;color:#0d3145;box-shadow:0 3px 16px rgba(12,45,60,.025)}
.wa10-head{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.wa10-eyebrow{color:#008d80;font-size:10px;letter-spacing:.11em;font-weight:800;margin-bottom:8px}.wa10-head h2{font-size:19px;font-weight:750;letter-spacing:-.035em;color:#10354c;margin:0 0 6px}.wa10-head p{font-size:12px;color:#7290a5;line-height:1.55;margin:0;max-width:680px}.wa10-chip{font-size:10px;font-weight:700;white-space:nowrap;padding:6px 9px;border:1px solid #dce6eb;border-radius:999px;color:#647d8c;background:#f3f7f9}.wa10-chip-safe{background:#e8f8f2;border-color:#b8e5d6;color:#078c79}.wa10-chip-review{background:#fff8e8;border-color:#f0dcb4;color:#a66b0b}
.wa10-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:19px 0}.wa10-stats>div{border:1px solid #dce7ed;border-radius:8px;min-height:91px;padding:12px 13px;background:#fff;display:flex;flex-direction:column;gap:5px}.wa10-stats span{color:#7391a6;font-size:11px}.wa10-stats strong{font-size:23px;letter-spacing:-.04em;color:#0e3450;line-height:1.1}.wa10-stats small{font-size:10px;color:#7391a6}.wa10-stats .wa10-stat-highlight{background:#ebf8f4;border-color:#bfebde}.wa10-stats .wa10-stat-highlight strong{color:#008f7d}
.wa10-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wa10-controls>div{border:1px solid #dce7ed;background:#fbfdfe;border-radius:9px;padding:14px 15px}.wa10-panel-title{display:flex;flex-direction:column;gap:3px}.wa10-panel-title strong{font-size:13px;color:#12374b}.wa10-panel-title small{color:#7b95a5;font-size:11px}.wa10-run-actions,.wa10-schedule-row{display:flex;align-items:flex-end;gap:12px;margin-top:15px}.wa10-run-actions label,.wa10-schedule-row label:not(.wa10-checkbox){display:flex;flex-direction:column;gap:4px;color:#65879c;font-size:11px;font-weight:600}.wa10-run-actions select,.wa10-schedule-row select{border:1px solid #d5e2e9;border-radius:7px;background:#fff;color:#12364c;padding:9px 11px;min-width:85px;font-size:12px}.wa10-run-actions button,.wa10-secondary{background:#008f84;border:1px solid #008f84;border-radius:7px;color:#fff;font-size:12px;font-weight:700;padding:10px 15px;cursor:pointer}.wa10-run-actions button:disabled{opacity:.5;cursor:not-allowed}.wa10-secondary{background:#fff;color:#008e82;margin-top:12px}.wa10-run-progress{display:flex;align-items:center;justify-content:space-between;margin-top:12px;font-size:11px;color:#5f7d90}.wa10-run-progress b{color:#008f84}.wa10-checkbox{display:flex;gap:7px;align-items:center;font-size:11px;color:#335970}.wa10-checkbox input{accent-color:#00988b}.wa10-schedule>small,.wa10-helper{display:block;margin-top:8px;color:#88a0ae;font-size:10px;line-height:1.5}.wa10-notice,.wa10-error{padding:10px 12px;font-size:12px;border-radius:7px;margin-top:10px;background:#ecf8f4;color:#007f71}.wa10-error{background:#fff0ea;color:#a5432b}
.wa10-evidence-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:20px 0 10px}.wa10-evidence-head strong{font-size:13px}.wa10-evidence-head small{color:#8399aa;font-size:11px}.wa10-evidence-list{border:1px solid #e0e9ef;border-radius:8px;overflow:hidden}.wa10-evidence-item{display:flex;align-items:center;gap:12px;padding:10px 12px;border-bottom:1px solid #e7eef2;font-size:11px}.wa10-evidence-item:last-child{border-bottom:0}.wa10-evidence-main{flex:1;min-width:150px;display:flex;flex-direction:column;gap:3px}.wa10-evidence-main strong{font-size:12px;color:#0e3549}.wa10-evidence-main small{color:#7891a4}.wa10-evidence-item a,.wa10-evidence-item button{color:#008c80;text-decoration:none;background:none;border:0;cursor:pointer;font-size:11px;font-weight:700;white-space:nowrap}.wa10-empty{padding:16px;border:1px dashed #d8e5eb;border-radius:8px;font-size:12px;color:#7d94a1}.wa10-footer{font-size:10px;color:#809ba9;margin:11px 0 0}
.wa10-public-pill{display:inline-block;background:#eaf7f3;color:#068b7c;border:1px solid #b9e2d8;border-radius:999px;padding:2px 7px;font-size:10px;font-weight:700;margin-top:4px}.wa10-proof{border:1px solid #bce5dc;border-radius:8px;background:#f0faf6;padding:11px 12px;margin:12px 0;color:#164b49}.wa10-proof strong{display:block;font-size:12px;margin-bottom:4px}.wa10-proof p{font-size:11px;color:#4e7a78;margin:4px 0}.wa10-proof a{font-size:11px;color:#087e75;font-weight:700}.wa10-contacts-flag{display:inline-block;margin:4px 0 0;color:#008f80;font-size:10px;font-weight:700}
@media(max-width:980px){.wa10-stats{grid-template-columns:repeat(2,1fr)}.wa10-controls{grid-template-columns:1fr}.wa10-head{flex-direction:column}}@media(max-width:580px){.wa10-evidence-item{flex-wrap:wrap}.wa10-public{padding:15px}.wa10-stats{gap:7px}}
</style>
